#include <iostream>
using namespace std;
class IntBuffer {
public:
    int* data; int size;
    IntBuffer(int n) : size(n), data(new int[n]()) {}
    ~IntBuffer() { delete[] data; }
    IntBuffer& operator=(const IntBuffer& other) {
        if (this == &other) return *this;
        delete[] data;
        size = other.size;
        data = new int[size];
        for (int i = 0; i < size; ++i) data[i] = other.data[i];
        return *this;
    }
};

